cssCode:
.neu-player {
  width: 280px; height: 100px; border-radius: 20px;
  background: #e0e5ec;
  box-shadow: 9px 9px 16px rgb(163,177,198,0.6), -9px -9px 16px rgba(255,255,255, 0.5);
  display: flex; align-items: center; padding: 0 20px; box-sizing: border-box; gap: 15px;
}
.neu-btn {
  width: 50px; height: 50px; border-radius: 50%; background: #e0e5ec;
  box-shadow: 5px 5px 10px rgb(163,177,198,0.6), -5px -5px 10px rgba(255,255,255, 0.6);
  display: flex; align-items: center; justify-content: center; cursor: pointer; color: #ff007f; font-size: 20px;
  transition: box-shadow 0.2s;
}
.neu-btn:active {
  box-shadow: inset 5px 5px 10px rgb(163,177,198,0.6), inset -5px -5px 10px rgba(255,255,255, 0.6);
}
.progress-bar {
  flex: 1; height: 12px; border-radius: 6px; background: #d1d9e6;
  box-shadow: inset 3px 3px 6px rgb(163,177,198,0.6), inset -3px -3px 6px rgba(255,255,255, 0.5);
  overflow: hidden; position: relative;
}
.progress-fill {
  width: 60%; height: 100%;
  background: linear-gradient(90deg, #ff9a9e 0%, #fecfef 99%, #fecfef 100%);
  border-radius: 6px; animation: progressAnim 2s infinite alternate;
}
@keyframes progressAnim { 0% { width: 10%; } 100% { width: 90%; } }

